func (forcedSSOGovernanceV103) TableName() string { return "governance_settings" }

func forcedSSOMigration(db *gorm.DB) error {
	groups := []struct {
		model   any
		fields  []string
		primary bool
	}{
		{&forcedSSOGovernanceV103{}, []string{"ForcedSSOEnabled", "AuthenticationPolicyRevision", "EmergencyAdminID", "EmergencyAdminCreatedAt"}, false},
		{&forcedSSOSessionV103{}, []string{"EmergencyPolicyRevision", "EmergencyUserCreatedAt", "EmergencyMFAGeneration", "EmergencyPasswordDigest", "EmergencyFactorCompletedAt"}, true},
		{&forcedSSOMFAChallengeV103{}, []string{"EmergencyPolicyRevision", "EmergencyUserCreatedAt", "EmergencyMFAGeneration", "EmergencyPasswordDigest", "EmergencyFactorCompletedAt"}, true},
	}
	for _, group := range groups {
		if !db.Migrator().HasTable(group.model) {
			return fmt.Errorf("missing authentication policy predecessor table")
		}
		stmt := &gorm.Statement{DB: db}
		if err := stmt.Parse(group.model); err != nil {
			return err
		}
		missing := false
		for _, name := range group.fields {
			if !db.Migrator().HasColumn(group.model, name) {
				missing = true
			}
		}
		if missing {
			// Resuming interrupted MySQL AddColumn is safe only for pristine new facts.
			// No partially retained emergency authority is defaulted or reconstructed.
			query := db.Table(stmt.Schema.Table)
			if group.primary {
				query = query.Where("OCTET_LENGTH(primary_method) = ?", 9).Where("primary_method = ?", "emergency")
			} else {
				query = query.Where("1 = 0")
			}
			var bad int64
			if err := query.Count(&bad).Error; err != nil {
				return err
			}
			if bad != 0 {
				return fmt.Errorf("nonpristine partial authentication policy")
			}
			for _, name := range group.fields {
				if !db.Migrator().HasColumn(group.model, name) {
					continue
				}
				f := stmt.Schema.FieldsByName[name]
				var bad int64
				q := db.Table(stmt.Schema.Table)
				switch name {
				case "ForcedSSOEnabled":
					q = q.Where(f.DBName+" IS NULL OR "+f.DBName+" <> ?", false)
				case "AuthenticationPolicyRevision":
					q = q.Where(f.DBName+" IS NULL OR OCTET_LENGTH("+f.DBName+") <> 64 OR "+f.DBName+" <> ?", strings.Repeat("0", 64))
				default:
					if f.FieldType.Kind() == reflect.Pointer {
						q = q.Where(f.DBName + " IS NOT NULL")
					} else {
						q = q.Where(f.DBName + " IS NULL OR OCTET_LENGTH(" + f.DBName + ") <> 0")
					}
				}
				if err := q.Count(&bad).Error; err != nil {
					return err
				}
				if bad != 0 {
					return fmt.Errorf("nonpristine partial authentication policy")
				}
			}
		}
		for _, name := range group.fields {
			if !db.Migrator().HasColumn(group.model, name) {
				if err := db.Migrator().AddColumn(group.model, name); err != nil {
					return err
				}
			}
		}
		if err := validateForcedSSOColumnsV103(db, group.model, group.fields); err != nil {
			return err
		}
	}
	// V100's physical shape/index validator remains valid: only the named CHECK
	// changes. Retained projection1 observations are never rewritten or promoted.
	if err := validateRuntimeInstallationColumnsV100(db); err != nil {
		return err
	}
	if err := validateForcedSSOInstallationIndexesV103(db); err != nil {
		return err
	}
	return forcedSSOConstraintsV103(db)
}

func forcedSSOConstraintsV103(db *gorm.DB) error {
	checks := []struct {
		model any
		name  string
	}{
		{&forcedSSOGovernanceV103{}, "ck_governance_authentication_policy"},
		{&forcedSSOSessionV103{}, "ck_sessions_oidc_primary"},
		{&forcedSSOMFAChallengeV103{}, "ck_mfa_challenges_oidc_primary"},
		{&forcedSSOInstallationV103{}, "ck_runtime_installation_projection"},
	}
	// Validate every retained row before the first DROP; SQL UNKNOWN is rejected.
	for _, v := range checks {
		stmt := &gorm.Statement{DB: db}
		if err := stmt.Parse(v.model); err != nil {
			return err
		}
		c, ok := stmt.Schema.ParseCheckConstraints()[v.name]
		if !ok {
			return fmt.Errorf("missing frozen authentication policy check")
		}
		var bad int64
		if err := db.Table(stmt.Schema.Table).Where("NOT (" + c.Constraint + ") OR (" + c.Constraint + ") IS NULL").Count(&bad).Error; err != nil {
			return err
		}
		if bad != 0 {
			return fmt.Errorf("invalid retained authentication policy")
		}
	}
	for _, v := range checks {
		if db.Migrator().HasConstraint(v.model, v.name) {
			if err := db.Migrator().DropConstraint(v.model, v.name); err != nil {
				return err
			}
		}
		if err := db.Migrator().CreateConstraint(v.model, v.name); err != nil {
			return err
		}
	}
	return nil
}

func validateForcedSSOColumnsV103(db *gorm.DB, model any, names []string) error {
	stmt := &gorm.Statement{DB: db}
	if err := stmt.Parse(model); err != nil {
		return err
	}
	columns, err := db.Migrator().ColumnTypes(model)
	if err != nil {
		return err
	}
	byName := map[string]gorm.ColumnType{}
	for _, c := range columns {
		if _, ok := byName[c.Name()]; ok {
			return fmt.Errorf("invalid authentication policy column set")
		}
		byName[c.Name()] = c
	}
	for _, name := range names {
		f := stmt.Schema.FieldsByName[name]
		if f == nil {
			return fmt.Errorf("unknown frozen authentication policy field")
		}
		c, ok := byName[f.DBName]
		if !ok {
			return fmt.Errorf("missing authentication policy column")
		}
		nullable, known := c.Nullable()
		wantNullable := f.FieldType.Kind() == reflect.Pointer
		pk, pkKnown := c.PrimaryKey()
		if !known || nullable != wantNullable || !pkKnown || pk {
			return fmt.Errorf("invalid authentication policy column authority")
		}
		kind := strings.ToLower(c.DatabaseTypeName())
		value, hasDefault := c.DefaultValue()
		if f.HasDefaultValue {
			actual := strings.TrimSpace(value)
			actual = strings.TrimSuffix(actual, "::character varying")
			if len(actual) >= 2 && actual[0] == '\'' && actual[len(actual)-1] == '\'' {
				actual = actual[1 : len(actual)-1]
			}
			if string(f.DataType) == "bool" {
				actual = strings.ToLower(actual)
				if actual == "0" {
					actual = "false"
				}
			}
			if !hasDefault || actual != f.DefaultValue {
				return fmt.Errorf("invalid authentication policy default")
			}
		} else if hasDefault && strings.TrimSpace(value) != "" && !strings.EqualFold(strings.TrimSpace(value), "NULL") {
			return fmt.Errorf("invalid authentication policy default")
		}
		switch string(f.DataType) {
		case "string":
			n, known := c.Length()
			if !known || n != int64(f.Size) || kind != "varchar" && kind != "character varying" {
				return fmt.Errorf("invalid authentication policy string")
			}
		case "bool":
			if kind != "bool" && kind != "boolean" && kind != "tinyint" {
				return fmt.Errorf("invalid authentication policy boolean")
			}
		case "time":
			precision, _, known := c.DecimalSize()
			if !known || precision != 6 || kind != "timestamp" && kind != "timestamptz" && kind != "datetime" {
				return fmt.Errorf("invalid authentication policy timestamp")
			}
		default:
			return fmt.Errorf("invalid authentication policy field")
		}
	}
	return nil
}

func validateForcedSSOInstallationIndexesV103(db *gorm.DB) error {
	model := &forcedSSOInstallationV103{}
	stmt := &gorm.Statement{DB: db}
	if err := stmt.Parse(model); err != nil {
		return err
	}
	for _, index := range stmt.Schema.ParseIndexes() {
		// Reuse the database-owned ordered metadata adapter; GORM GetIndexes loses
		// PostgreSQL key order. DDL still uses GORM, with bound metadata identities.
		columns, err := credentialAttemptStatisticsIndexColumns(db, stmt.Schema.Table, index.Name)
		if err != nil {
			return err
		}
		if len(columns) != len(index.Fields) {
			return fmt.Errorf("invalid runtime installation index %s", index.Name)
		}
		for i, c := range columns {
			if !c.ColumnName.Valid || c.ColumnName.String != index.Fields[i].DBName || !c.Position.Valid || c.Position.Int64 != int64(i+1) || !c.IsUnique.Valid || c.IsUnique.Bool != (index.Class == "UNIQUE") || c.PrefixLength.Valid {
				return fmt.Errorf("invalid runtime installation index %s", index.Name)
			}
		}
	}
	return nil
}
